-- =============================================================================
-- University of Nigeria, Nsukka — Faculty of Social Sciences — Economics
-- Course outlines transcribed from the Faculty of Social Sciences course
-- handbook (scanned copy), covering the Four-Year B.Sc Degree Programme in
-- Economics: all four years, both semesters, including required ancillary,
-- general-studies and elective courses (not just Economics majors).
-- =============================================================================
-- Run in the Supabase SQL Editor. Safe to run more than once: existing rows
-- for this department are removed first, so it updates rather than duplicates.
--
-- SEMESTERS: the handbook explicitly labels every course "FIRST SEMESTER" or
-- "SECOND SEMESTER" in its programme-structure tables, so those stated values
-- are used directly — no guessing was needed here.
--
-- ANCILLARY/GSP/ELECTIVE COURSES FROM OTHER DEPARTMENTS: courses such as
-- COS 101/102, MTH 111/121/122, GSP 1xx/2xx, PSY 101, SOC 101, GEO 101/102/214,
-- STA 132/172, POL 241, SOC 252 and CED 341/342 appear in the Economics
-- timetable but their own descriptions are not printed in the Economics
-- section of this document. They are included with real code/title/units so
-- the timetable is complete, but with an empty description/topics — this app
-- backfills a real description for these from a sibling department's own
-- outline file where one is available (e.g. Sociology's own SOC 101 entry),
-- and leaves it blank where no verified source exists anywhere in this app yet.
--
-- PAGE-QUALITY NOTE: the photograph of the page carrying the ECO 101, ECO 102,
-- ECO 121 and ECO 122 descriptions (page 6 of the source scan) is out of
-- focus. The course codes, titles and unit counts on it are clearly legible;
-- the paragraph descriptions were transcribed to the best legible reading of
-- that same blurred photo (cross-checked word by word), not invented.
-- =============================================================================

delete from public.course_outlines
 where institution = 'University of Nigeria, Nsukka'
   and department = 'Economics';

insert into public.course_outlines
  (course_code, course_title, institution, faculty, department, level,
   semester, credit_units, description, topics, contributor_name)
values
  ('ECO 101', 'Principles of Economics I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '100 Level', 'first', 2, 'Nature and significance of Economics; The methodology of economics; Economic tools of analysis; Theories of demand and supply; Elementary analysis; Dynamic theory of price; Elements of price theory; Production theory: Output, cost, law of diminishing returns; Market structure: Perfect competition, monopoly, oligopoly etc; Elementary theory of welfare economics; Determinants for and pricing of productive factors; Interest rate and profit.', '["Nature and significance of Economics", "The methodology of economics", "Economic tools of analysis", "Theories of demand and supply", "Elementary analysis", "Dynamic theory of price", "Elements of price theory", "Production theory: Output, cost, law of diminishing returns", "Market structure: Perfect competition, monopoly, oligopoly etc", "Elementary theory of welfare economics", "Determinants for and pricing of productive factors", "Interest rate and profit"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 121', 'Introduction to Accounting', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '100 Level', 'first', 2, 'The nature, scope and purposes of accounting; Evolution of accounting doctrines; The users of financial statements and their information requirements; Rules and types of accounts; Accounting Theory: terminologies, concepts, assumptions, and conventions; Theory and mechanics of double-entry book-keeping; books of original entry, cash book and petty cash book, the ledger classifications; Trial Balance and correction of errors; Suspense Account; Accounting for depreciation and non-current assets; Basic financial statements; Preparation of final accounts of business concerns without adjustments; statement of financial position; Statement of Comprehensive income; nature and application of funds statements; The classification of assets and measurement of business incomes; The interpretation of accounts; Significant accounting issues of value; Computer Accounting, Applications and Software Packages.', '["The nature, scope and purposes of accounting", "Evolution of accounting doctrines", "The users of financial statements and their information requirements", "Rules and types of accounts", "Accounting Theory: terminologies, concepts, assumptions, and conventions", "Theory and mechanics of double-entry book-keeping; books of original entry, cash book and petty cash book, the ledger classifications", "Trial Balance and correction of errors", "Suspense Account", "Accounting for depreciation and non-current assets", "Basic financial statements", "Preparation of final accounts of business concerns without adjustments; statement of financial position", "Statement of Comprehensive income; nature and application of funds statements", "The classification of assets and measurement of business incomes", "The interpretation of accounts", "Significant accounting issues of value", "Computer Accounting, Applications and Software Packages"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 131', 'Introduction to Economic Statistics I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '100 Level', 'first', 2, 'Meaning and scope of statistics; Statistical methods and their purposes; Data: primary data, secondary data, data frequency, rounding of data; Population and sample [including inductive and descriptive statistics]; Variables: discrete and continuous; Functions; Rectangular coordinates; Graphs; Frequency distributions [including arrays, frequency tables, class intervals and limits, class size, width, general rules for forming frequency distributions, histograms and frequency polygons, relative frequency distributions, cumulative frequency distributions, ogives, frequency curves]; Measures of central tendency [unweighted and weighted arithmetic mean and their properties, arithmetic mean for grouped data, median and mode, and the empirical relations between the three; Geometric mean, harmonic mean, the root mean square, quartiles, inter-quartiles, deciles, percentiles etc]; Measures of dispersion: the range, variation, mean deviation, semi-inter-quartile range, the variance, Shephard''s correction for variance, standard deviation, properties of standard deviation, Empirical relation between measures of dispersion; Relative dispersion, Coefficient of variation, standard variables and standard scores; Population moments, Skewness and kurtosis [ungrouped and grouped data]; Index numbers.', '["Meaning and scope of statistics", "Statistical methods and their purposes", "Data: primary data, secondary data, data frequency, rounding of data", "Population and sample", "Variables: discrete and continuous; Functions; Rectangular coordinates; Graphs", "Frequency distributions", "Measures of central tendency", "Measures of dispersion", "Relative dispersion, Coefficient of variation, standard variables and standard scores", "Population moments, Skewness and kurtosis", "Index numbers"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 102', 'Principles of Economics II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '100 Level', 'second', 2, 'Elementary principles of macroeconomics and microeconomics; National income determination; The circular flow of income; Injections, withdrawals and the multiplier; Income determination; consumption, saving and investment functions; Nature and features of money; The banking system and the supply of money; Money supply and price level; International trade; Exchange rate and comparative advantage; Foreign trade and domestic economy; Economic growth; Elementary notion of economic planning; Introduction to Marxist economic theory.', '["Elementary principles of macroeconomics and microeconomics", "National income determination", "The circular flow of income; Injections, withdrawals and the multiplier", "Income determination; consumption, saving and investment functions", "Nature and features of money", "The banking system and the supply of money", "Money supply and price level", "International trade; Exchange rate and comparative advantage", "Foreign trade and domestic economy", "Economic growth", "Elementary notion of economic planning", "Introduction to Marxist economic theory"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 122', 'Introduction to Business Management', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '100 Level', 'second', 2, 'Concept of business, organization and management; Definitional problems; Evolution of management theory; relevance of management theories to business organization, non-business organization and the household; Management functions; Business environment; types and roles of each to the success of business organization; Business financing: different types of business financing, advantages and disadvantages of different types of business management; Why some businesses fail and others succeed; Quantitative aids to management.', '["Concept of business, organization and management", "Definitional problems", "Evolution of management theory", "Relevance of management theories to business organization, non-business organization and the household", "Management functions", "Business environment; types and roles of each to the success of business organization", "Business financing: different types of business financing, advantages and disadvantages of different types of business management", "Why some businesses fail and others succeed", "Quantitative aids to management"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 124', 'Principles of Business Finance', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '100 Level', 'second', 2, 'Introduction: meaning, basic concept and objectives of business finance; Role of financial markets and opportunity cost of capital; Valuation: fixed income securities, common stock; Financial Management of firms: basic theory and practice, investment decision making; Financial statements and financial analysis; Time value of money; Capital budgeting and risk-return tradeoff: measuring risks; Portfolio theory: managing risk, the capital asset pricing model; the cost of capital, capital structure, and the role of financial markets.', '["Introduction: meaning, basic concept and objectives of business finance", "Role of financial markets and opportunity cost of capital", "Valuation: fixed income securities, common stock", "Financial Management of firms: basic theory and practice, investment decision making", "Financial statements and financial analysis", "Time value of money", "Capital budgeting and risk-return tradeoff: measuring risks", "Portfolio theory: managing risk, the capital asset pricing model", "The cost of capital, capital structure, and the role of financial markets"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 132', 'Introduction to Economic Statistics II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '100 Level', 'second', 2, 'Elementary sampling theory [including random samples and random numbers, sampling with and without replacement], sampling distributions, distribution of means and distribution of proportions, central limit theorem; Distribution of differences and sums, standard errors; Statistical estimation theory [including parameters, unbiased estimates, point and interval estimates, confidence intervals]; Statistical decision theory [including statistical test of hypotheses, Type I and Type II errors, test involving normal distribution, p-values, test for sample differences]; Small Sampling theory and statistical inference [including student''s t distribution, Chi-square distribution, F-distribution, confidence intervals for standard errors, degrees of freedom].', '["Elementary sampling theory", "Sampling distributions, distribution of means and distribution of proportions, central limit theorem", "Distribution of differences and sums, standard errors", "Statistical estimation theory", "Statistical decision theory", "Small Sampling theory and statistical inference"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 201', 'Microeconomic Theory I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '200 Level', 'first', 2, 'Introduction to microeconomics; Problem of scarce resources; Allocation of resources in product and factor markets with applications to Nigeria and other economies; Supply and demand theory; Cobweb theory; Theory of consumer behavior: utility, preferences, indifference curves, budget constraints; Substitution and Income effects of price change in consumers'' demand; equilibrium concept; Possibility of disequilibrium; Partial equilibrium analyses; General equilibrium analyses; Introduction to economic dynamics.', '["Introduction to microeconomics", "Problem of scarce resources", "Allocation of resources in product and factor markets with applications to Nigeria and other economies", "Supply and demand theory; Cobweb theory", "Theory of consumer behavior: utility, preferences, indifference curves, budget constraints", "Substitution and Income effects of price change in consumers'' demand; equilibrium concept", "Possibility of disequilibrium", "Partial equilibrium analyses; General equilibrium analyses", "Introduction to economic dynamics"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 203', 'Macroeconomic Theory I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '200 Level', 'first', 2, 'Introduction to macroeconomics; Goals of macroeconomic analysis; National Income Accounting; Alternative approaches to GNP estimation; GNP and related macroeconomic aggregates; Conceptual problems of estimation and use of national accounts; Introduction to a simple macro-model of a market economy.', '["Introduction to macroeconomics", "Goals of macroeconomic analysis", "National Income Accounting", "Alternative approaches to GNP estimation", "GNP and related macroeconomic aggregates", "Conceptual problems of estimation and use of national accounts", "Introduction to a simple macro-model of a market economy"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 221', 'Monetary Economics and Finance', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '200 Level', 'first', 2, 'Evolution of money; Barter system; Money: definition, functions and characteristics; Monetary Theories: the quantity theory of money – Classification of money and near money; Monetary Theories: the quantity theory of money – Fisher cash transaction approach, the Cambridge cash balance approach, the portfolio balance approach, Friedman''s restatement of the quantity theory of money; The liquidity trap approach; Sources of business finance; Risks in businesses: Commercial money; The Supply of Money; banking: principles, functions, organization and structure; Microfinance institutions; Central banking; Payment principles and functions; Branch banking; Group banking etc; Payment Systems.', '["Evolution of money; Barter system", "Money: definition, functions and characteristics", "Monetary Theories: the quantity theory of money", "Classification of money and near money", "Fisher cash transaction approach, the Cambridge cash balance approach, the portfolio balance approach, Friedman''s restatement of the quantity theory of money", "The liquidity trap approach", "Sources of business finance; Risks in businesses", "Commercial banking: principles, functions, organization and structure", "Microfinance institutions", "Central banking; Payment principles and functions", "Branch banking; Group banking etc", "Payment Systems"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 231', 'Intermediate Economic Statistics I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '200 Level', 'first', 2, 'Probability theory and probability distributions [including discrete and continuous probability distributions]; Probability sampling from tables of random numbers; Probability tree; Applications of probability theory to economics; Basic probability theorems; Types and distributions of random variables: Discrete and continuous random variables; Exponential density and gamma density; Bernoulli, Binomial, Poisson, Geometric, Hyper-geometric, Normal distributions; Generation of statistical events from set-theory; Combinatorial Analysis; Expectations and moments of random variables.', '["Probability theory and probability distributions", "Probability sampling from tables of random numbers; Probability tree", "Applications of probability theory to economics; Basic probability theorems", "Types and distributions of random variables: Discrete and continuous random variables", "Exponential density and gamma density; Bernoulli, Binomial, Poisson, Geometric, Hyper-geometric, Normal distributions", "Generation of statistical events from set-theory; Combinatorial Analysis", "Expectations and moments of random variables"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 233', 'Intermediate Mathematics for Economists I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '200 Level', 'first', 2, 'Linear Algebra: detailed treatment of vectors and matrices, Rank of a matrix, Trace, Eigen values and Eigenvectors; Linear Programming; Input-output analysis; Game theory (introduction); Differential and integral calculus; Comparative statics analysis; First-order differential equations: First-order difference equations; Applications of first-order differential and difference equations to economics (consumer behaviour, demand and supply analysis).', '["Linear Algebra: detailed treatment of vectors and matrices, Rank of a matrix, Trace, Eigen values and Eigenvectors", "Linear Programming; Input-output analysis", "Game theory (introduction)", "Differential and integral calculus; Comparative statics analysis", "First-order differential equations: First-order difference equations", "Applications of first-order differential and difference equations to economics (consumer behaviour, demand and supply analysis)"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 281', 'History and Structure of the Nigerian Economy I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '200 Level', 'first', 2, 'An overview of the Nigerian economy: pre-colonial period, colonial period, post-independence period with special regard to development of economic and social organization; The Nigerian economic system: natural and human resources endowments; An overview of monetary and development institutions in Nigeria; The sectors of the Nigerian economy: their relative sizes, importance and contributions to Nigerian economic development; Sectoral interdependence in the Nigerian economy.', '["An overview of the Nigerian economy: pre-colonial period, colonial period, post-independence period with special regard to development of economic and social organization", "The Nigerian economic system: natural and human resources endowments", "An overview of monetary and development institutions in Nigeria", "The sectors of the Nigerian economy: their relative sizes, importance and contributions to Nigerian economic development", "Sectoral interdependence in the Nigerian economy"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 223', 'Intermediate Business Accounting', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '200 Level', 'second', 2, 'Trial balance and adjustments; Preparation of financial statements of business concerns; Bank reconciliation; Inventories and cost of goods sold: specific invoice prices, average cost, first-in first-out, last-in first-out; Budgets and budgeting; Nature of funds flow; Sources and application of funds statements; Cash flow distinguished from funds flow; Generally accepted accounting principles: history, structure and functions of the financial reporting council; Introduction to International Financial Reporting Standards (IFRS); Computer accounting applications and software packages.', '["Trial balance and adjustments", "Preparation of financial statements of business concerns", "Bank reconciliation", "Inventories and cost of goods sold: specific invoice prices, average cost, first-in first-out, last-in first-out", "Budgets and budgeting", "Nature of funds flow; Sources and application of funds statements", "Cash flow distinguished from funds flow", "Generally accepted accounting principles: history, structure and functions of the financial reporting council", "Introduction to International Financial Reporting Standards (IFRS)", "Computer accounting applications and software packages"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 202', 'Microeconomic Theory II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '200 Level', 'second', 2, 'Cost theory and cost curves; Pricing of production factors; Pricing and output decisions under perfect competition, monopoly, oligopolistic competition, duopoly, duopsony, monopsony; General equilibrium of exchange; Theory of comparative advantage.', '["Cost theory and cost curves", "Pricing of production factors", "Pricing and output decisions under perfect competition, monopoly, oligopolistic competition, duopoly, duopsony, monopsony", "General equilibrium of exchange", "Theory of comparative advantage"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 204', 'Macroeconomic Theory II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '200 Level', 'second', 2, 'Building the core macroeconomic model: the commodity market, the money market, the labour market; Economic stabilization: the classical, Keynesian and monetarist systems; Monetary and fiscal policies, price control and inflation.', '["Building the core macroeconomic model: the commodity market, the money market, the labour market", "Economic stabilization: the classical, Keynesian and monetarist systems", "Monetary and fiscal policies, price control and inflation"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 232', 'Intermediate Economic Statistics II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '200 Level', 'second', 2, 'Basic sampling and surveys; Types of simple random sampling; Expectation and variance of sample mean; Estimation of population variance; Normal approximation to sampling distribution; Stratified random sampling; Correlation theory [including linear correlation, measures of correlation, derivation of least squares lines, standard errors of estimates, explained and unexplained variations, correlation coefficients, correlation of time series etc]; Analysis of variance- total variation, variation within and between treatments, F-test, One-, Two- ways classifications]; Non-parametric tests – Mann-Whitney U tests; Sampling and sampling distributions; Estimation theory; Hypothesis testing; Regression analysis: Simple and Multiple; Statistical tests of significance; Multiple Analysis of Variance.', '["Basic sampling and surveys; Types of simple random sampling", "Expectation and variance of sample mean; Estimation of population variance", "Normal approximation to sampling distribution; Stratified random sampling", "Correlation theory", "Analysis of variance- total variation, variation within and between treatments, F-test, One-, Two- ways classifications", "Non-parametric tests – Mann-Whitney U tests", "Sampling and sampling distributions; Estimation theory; Hypothesis testing", "Regression analysis: Simple and Multiple; Statistical tests of significance; Multiple Analysis of Variance"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 234', 'Intermediate Mathematics for Economists II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '200 Level', 'second', 2, 'Linear Algebra: Jacobian and Hessian matrices; Quadratic forms and applications to optimization in economics (cost minimization, profit maximization, utility maximization, comparative statics, etc.); Boundary solutions: Kuhn-Tucker conditions and applications to consumer and producer theory; Second-order differential equations; Second-order difference equations; Methods of solution and their stability properties.', '["Linear Algebra: Jacobian and Hessian matrices", "Quadratic forms and applications to optimization in economics (cost minimization, profit maximization, utility maximization, comparative statics, etc.)", "Boundary solutions: Kuhn-Tucker conditions and applications to consumer and producer theory", "Second-order differential equations; Second-order difference equations", "Methods of solution and their stability properties"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 236', 'Computing Applications for Economists', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '200 Level', 'second', 2, 'Relevance of ICT in Economics; Understanding EXCEL: data generating process; Creating Graphs; Manipulating EXCEL Worksheet Data; Data Transformation using EXCEL; Practical modeling using EXCEL; Simple and Multiple Regression analysis using EXCEL; Understanding some of these econometric softwares: PC-GIVE, MICROFIT, RATS, GAUSS PROGRAM etc, E-VIEWS, STATA, MATLAB, OX-METRICS; Understanding SPSS: data input, data editor, data manipulation, data transformation, statistical/econometric analysis, output management; Understanding power point: creating a presentation, power-point views, adding pictures and tables; Slide types and layouts; Transition and animation effects; Running a slide show; Mini-proposal presentation on any economic issue using PPT slides.', '["Relevance of ICT in Economics", "Understanding EXCEL: data generating process; Creating Graphs; Manipulating EXCEL Worksheet Data; Data Transformation using EXCEL", "Practical modeling using EXCEL; Simple and Multiple Regression analysis using EXCEL", "Understanding econometric softwares: PC-GIVE, MICROFIT, RATS, GAUSS PROGRAM etc, E-VIEWS, STATA, MATLAB, OX-METRICS", "Understanding SPSS: data input, data editor, data manipulation, data transformation, statistical/econometric analysis, output management", "Understanding power point: creating a presentation, power-point views, adding pictures and tables; Slide types and layouts; Transition and animation effects", "Running a slide show; Mini-proposal presentation on any economic issue using PPT slides"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 282', 'History and Structure of the Nigerian Economy II', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '200 Level', 'second', 2, 'Nigeria''s economic growth and development: growth of income, employment, wages and prices; National Income and expenditure; Money and monetary institutions; The quest for economic development and fiscal policy; Public development institutions and the quest for economic development; Trade and transportation; A study of social change; Agricultural and industrial production; Trade and transportation; A study of some key industries, e.g. oil, iron and steel, automobile and construction.', '["Nigeria''s economic growth and development: growth of income, employment, wages and prices", "National Income and expenditure", "Money and monetary institutions", "The quest for economic development and fiscal policy", "Public development institutions and the quest for economic development", "Trade and transportation", "A study of social change", "Agricultural and industrial production", "A study of some key industries, e.g. oil, iron and steel, automobile and construction"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 262', 'Urban and Regional Economics', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '200 Level', 'second', 2, 'Introduction to urban and regional economics and consumption within an urban locality; Nature and extent of spatial variation in welfare at the national and regional scales; Models/theories of spatial variation in factors that affect the growth or decline of cities and regions; Regional and urban problems in Nigeria and other selected countries; Urban land rents/rate determination; Urban housing and transportation problems and policies; Urban and regional factor markets; Rationale and instruments of regional policies the gains, problems and prospects of adopting a single currency within regions; Government policies on economic/social relations in cities; Efforts toward reducing regional disparities in economic opportunities and welfare.', '["Introduction to urban and regional economics and consumption within an urban locality", "Nature and extent of spatial variation in welfare at the national and regional scales", "Models/theories of spatial variation in factors that affect the growth or decline of cities and regions", "Regional and urban problems in Nigeria and other selected countries", "Urban land rents/rate determination", "Urban housing and transportation problems and policies", "Urban and regional factor markets", "Rationale and instruments of regional policies the gains, problems and prospects of adopting a single currency within regions", "Government policies on economic/social relations in cities", "Efforts toward reducing regional disparities in economic opportunities and welfare"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 264', 'Introduction to Environmental Economics', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '200 Level', 'second', 2, 'Introduction: emergence of environmental economics; Issues in the economic approach to environmental problems; Drivers of environmental impact; Poverty and inequality; Limits to growth; Concepts of sustainability; Environmental pollution, Pollution control.', '["Introduction: emergence of environmental economics", "Issues in the economic approach to environmental problems", "Drivers of environmental impact", "Poverty and inequality", "Limits to growth", "Concepts of sustainability", "Environmental pollution, Pollution control"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 266', 'Introduction to Health Economics', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '200 Level', 'second', 2, 'Introduction to health economics; Demand for health and healthcare; Production and supply of healthcare; Introduction to the market for healthcare; Market failure and the role of government in health and healthcare; Introduction to the organization of the health sector: primary, secondary and tertiary; National Health Insurance Scheme.', '["Introduction to health economics", "Demand for health and healthcare", "Production and supply of healthcare", "Introduction to the market for healthcare", "Market failure and the role of government in health and healthcare", "Introduction to the organization of the health sector: primary, secondary and tertiary", "National Health Insurance Scheme"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 271', 'Theories of Human Resources', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '200 Level', 'second', 2, 'Concepts of human resources and human capital; Origin of the concept of human capital; Importance of human capital in economic development; Strategies for the development of human capital, education, health and skills training; Human capital theories: screening/filter theory, dualistic theory etc; Problems of manpower development in developing countries; Manpower planning and utilization; the situation in developing countries; Theory of incentive and its impact on career choice.', '["Concepts of human resources and human capital; Origin of the concept of human capital", "Importance of human capital in economic development", "Strategies for the development of human capital, education, health and skills training", "Human capital theories: screening/filter theory, dualistic theory etc", "Problems of manpower development in developing countries", "Manpower planning and utilization; the situation in developing countries", "Theory of incentive and its impact on career choice"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 273', 'Labour Economics', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '200 Level', 'second', 2, 'Significance of labour in economics; Labour force: definition, determinants of size, composition and occupational distribution; Labour market: formal and informal sectors; features of the Nigerian labour market; Demand for labour and supply of labour in competitive markets; Labour market equilibrium; Economics of wage determination; Long-run supply of labour; Human capital theory and the New Home Economics.', '["Significance of labour in economics", "Labour force: definition, determinants of size, composition and occupational distribution", "Labour market: formal and informal sectors; features of the Nigerian labour market", "Demand for labour and supply of labour in competitive markets", "Labour market equilibrium", "Economics of wage determination", "Long-run supply of labour", "Human capital theory and the New Home Economics"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 301', 'Intermediate Microeconomic Theory I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '300 Level', 'first', 2, 'Advanced and mathematical treatment of the theory of consumer behaviour: Revealed preference theory; calculation of income and substitution effects, calculation of compensating and equivalent variations; Linear programming in utility maximization; Advanced price and output determination under perfect competition, monopoly, oligopoly etc; Exchange theory: offer curves and contract curves; Introduction to capital theory; Types of production functions.', '["Advanced and mathematical treatment of the theory of consumer behaviour: Revealed preference theory", "Calculation of income and substitution effects, calculation of compensating and equivalent variations", "Linear programming in utility maximization", "Advanced price and output determination under perfect competition, monopoly, oligopoly etc", "Exchange theory: offer curves and contract curves", "Introduction to capital theory", "Types of production functions"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 325', 'Public Sector Economics I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '300 Level', 'first', 2, 'Nature and structure of public sector; Public sector in Nigeria; Public Goods and their economic analysis; Free rider problem; Externalities; Concept of market failure, Role of Government; Governments and Insurance; Government failure; Collective action choice; Prisoners'' dilemma; Revenue and expenditure: meaning and theoretical relationship; Public expenditure deficit and its financing; Public sector versus private sector; Theories of public expenditure growth; Public expenditure in Nigeria: nature, trend and pattern.', '["Nature and structure of public sector; Public sector in Nigeria", "Public Goods and their economic analysis; Free rider problem; Externalities", "Concept of market failure, Role of Government", "Governments and Insurance; Government failure", "Collective action choice; Prisoners'' dilemma", "Revenue and expenditure: meaning and theoretical relationship", "Public expenditure deficit and its financing; Public sector versus private sector", "Theories of public expenditure growth", "Public expenditure in Nigeria: nature, trend and pattern"]'::jsonb, 'Department of Economics handbook'),
  ('ECO 331', 'Introduction to Econometrics I', 'University of Nigeria, Nsukka', 'Faculty of Social Sciences', 'Economics', '300 Level', 'first', 2, 'Nature and scope of econometrics; Stages in econometrics research; Revision of correlation analysis; Ordinary least squares: basic assumptions of classical linear regression models; Simple regression analysis; Multiple regression analysis; Statistical tests of significance of least squares estimates; Causality analysis in economics; Compulsory econometrics practical.', '["Nature and scope of econometrics; Stages in econometrics research", "Revision of correlation analysis", "Ordinary least squares: basic assumptions of classical linear regression models", "Simple regression analysis; Multiple regression analysis", "Statistical tests of significance of least squares estimates", "Causality analysis in economics", "Compulsory econometrics practical"]'::jsonb, 'Department of Economics handbook'),
